def minConnectedGroups(intervals, k):
    # Sort intervals by start and merge overlapping/touching ones
    intervals.sort()
    merged = []
    for start, end in intervals:
        if not merged or merged[-1][1] < start:
            merged.append([start, end])
        else:
            merged[-1][1] = max(merged[-1][1], end)

    n = len(merged)
    if n == 0:
        return 1  # the inserted interval itself forms one group

    # An inserted interval can join groups i..j iff merged[j].start - merged[i].end <= k
    best = 0   # largest number of groups that can be removed (j - i)
    j = 0
    for i in range(n):
        j = max(j, i)
        while j + 1 < n and merged[j + 1][0] - merged[i][1] <= k:
            j += 1
        best = max(best, j - i)
    return n - best
